    start1, end1 = interval1
    start2, end2 = interval2

    start = max(start1, start2)
    end = min(end1, end2)

    if start > end:
        return "NO"

    length = end - start + 1

    if is_prime(length):
        return "YES"
    else:
        return "NO"

