def below_zero(operations: List[int]) -> bool:
    """ You have a sequence of deposit and withdrawal transactions on a bank account that starts with a balance of zero. Determine if the balance ever drops below zero. Return True if it does, otherwise return False.
    >>> below_zero([1, 2, 3])
    False
    >>> below_zero([1, 2, -4, 5])
    True
    """
    balance = 0
    for transaction in operations:
        balance += transaction
        if balance < 0:
            return True
    return False

