def unique_digits(x):
    # Validate input
    if not all(isinstance(num, int) and num > 0 for num in x):
        raise ValueError("Input list must contain only positive integers")

    # Filter out numbers with even digits
    def has_even_digit(num):
        return any(int(digit) % 2 == 0 for digit in str(num))

    filtered_nums = [num for num in x if not has_even_digit(num)]

