from typing import List

def factorize(n: int) -> List[int]:
    def find_prime_factors(num):
        factors = []
        divisor = 2
        while divisor <= num:
            if num % divisor == 0:
                factors.append(divisor)
                num = num / divisor
            else:
                divisor += 1
        return factors

    prime_factors = find_prime_factors(n)
    prime_factors.sort()
