def cycpattern_check(a, b):
    def is_substring(s1, s2):
        return s2 in s1

    def generate_rotations(s):
        rotations = []
        for i in range(len(s)):
            rotations.append(s[i:] + s[:i])
        return rotations

    if is_substring(a, b):
        return True

    rotations = generate_rotations(b)
    for rotation in rotations:
        if is_substring(a, rotation):
