def hex_key(num):
    prime_digits = {'2', '3', '5', '7', 'B', 'D'}
    count = 0

    # Validate input
    if not all(char in '0123456789ABCDEF' for char in num):
        return 0

    # Convert hexadecimal number to decimal
    decimal_num = int(num, 16)

    # Count prime digits
    while decimal_num > 0:
        digit = decimal_num % 16
        if hex(digit).upper() in prime_digits:
            count += 1
        decimal_num //= 16

    return count

