from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    def calculate_max_depth(group: str) -> int:
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        return max_depth

    groups = paren_string.split()
    max_depths = [calculate_max_depth(group) for group in groups]

    return max_depths
